import Foundation
import Testing

/// A golden test vector file generated by `tools/test-vectors` (`make vectors`).
public struct VectorFile<Input: Decodable & Sendable, Expected: Decodable & Sendable>: Decodable, Sendable {
    public struct Vector: Decodable, Sendable, CustomTestStringConvertible {
        public let name: String
        public let input: Input
        public let expected: Expected

        public var testDescription: String { name }
    }

    public let generator: String
    public let source: String
    public let vectors: [Vector]

    /// Loads `Vectors/<name>.json` from a test bundle (`Bundle.module` of the test target).
    public static func load(_ name: String, from bundle: Bundle) throws -> [Vector] {
        guard let url = bundle.url(forResource: name, withExtension: "json", subdirectory: "Vectors") else {
            throw VectorFileError.missing(name)
        }
        return try JSONDecoder().decode(Self.self, from: Data(contentsOf: url)).vectors
    }
}

public enum VectorFileError: Error, Equatable {
    case missing(String)
    case invalidHex(String)
}

extension [UInt8] {
    /// Decodes a lowercase hex string as used in the vector files.
    public init(hex: String) throws {
        guard hex.count.isMultiple(of: 2) else { throw VectorFileError.invalidHex(hex) }
        var bytes: [UInt8] = []
        var index = hex.startIndex
        while index < hex.endIndex {
            let next = hex.index(index, offsetBy: 2)
            guard let byte = UInt8(hex[index..<next], radix: 16) else { throw VectorFileError.invalidHex(hex) }
            bytes.append(byte)
            index = next
        }
        self = bytes
    }
}
